  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, status, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, '{"text": "Masalah: File Penting Hilang Saat Dibutuhkan"}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, '{"text": "Laptop rusak, HP hilang, atau flashdisk korup — dan semua foto, dokumen kerja, serta tugas sekolah ikut lenyap. Kejadian seperti ini sangat umum: data hanya tersimpan di satu perangkat tanpa salinan cadangan. Akibatnya bisa fatal, dari kehilangan kenangan keluarga sampai harus mengulang pekerjaan berminggu-minggu."}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, '{"text": "Penjelasan: Apa Itu Cloud Storage"}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, '{"text": "Cloud storage adalah layanan penyimpanan file di server milik penyedia layanan (Google, Microsoft, Dropbox, dan lain-lain) yang bisa diakses lewat internet dari perangkat apa pun. File yang diunggah otomatis tersimpan di pusat data yang redundan — artinya ada banyak salinan di lokasi berbeda, sehingga jauh lebih aman dari kerusakan perangkat. Layanan populer umumnya memberi paket gratis (misalnya 15 GB) dan paket berbayar untuk kapasitas lebih besar."}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, '{"text": "Alat yang Dibutuhkan"}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, '{"items": ["Akun email aktif (untuk mendaftar layanan)", "Koneksi internet yang stabil", "Perangkat: HP, laptop, atau komputer", "Daftar kebutuhan: perkiraan ukuran file dan jumlah perangkat"]}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, '{"text": "Langkah: Memilih Cloud Storage yang Tepat"}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, '{"text": "Pertama, hitung kebutuhan: jumlahkan ukuran foto, video, dan dokumen penting Anda — lalu tambahkan cadangan 30 persen untuk pertumbuhan. Kedua, bandingkan paket gratis: perhatikan kapasitas, batas ukuran file per unggahan, dan apakah ada iklan atau batasan unduhan. Ketiga, uji coba 1-2 layanan selama seminggu: unggah file besar, buka dari HP dan laptop, dan coba fitur berbagi tautan. Keempat, periksa fitur keamanan: enkripsi saat transfer, verifikasi dua langkah, dan riwayat versi file. Kelima, baru putuskan: tetap di paket gratis atau naik ke paket berbayar bila kebutuhan melebihi kuota."}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, '{"text": "Risiko yang Perlu Diwaspadai"}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, '{"items": ["Ketergantungan internet: tanpa koneksi, file tidak bisa diakses — simpan salinan offline untuk file kritis", "Kebijakan berubah: paket gratis bisa dikurangi kapasitasnya sewaktu-waktu oleh penyedia", "Akun diretas: aktifkan verifikasi dua langkah dan gunakan kata sandi yang kuat dan unik", "Data sensitif: hindari menyimpan dokumen sangat rahasia tanpa enkripsi tambahan", "Sinkronisasi keliru: file yang dihapus di satu perangkat bisa terhapus di semua perangkat — periksa pengaturan sinkronisasi"]}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, '{"text": "Penyelesaian dan Tindak Lanjut"}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, '{"text": "Tetapkan rutinitas: unggah file penting setiap minggu, tinjau kapasitas tiap tiga bulan, dan simpan satu salinan cadangan di media fisik (harddisk eksternal) untuk data yang tidak boleh hilang. Dengan strategi 3-2-1 (tiga salinan, dua media berbeda, satu di luar lokasi), data Anda praktis aman dari bencana apa pun."}'::jsonb);
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, status, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, '{"text": "Masalah: Kulit Kering, Gatal, dan Mengelupas"}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, '{"text": "Kulit terasa kencang setelah mandi, muncul sisik halus di kaki dan tangan, kadang gatal hingga mengganggu tidur. Kulit kering (xerosis) sangat umum, terutama di ruangan ber-AC, saat cuaca panas berangin, atau karena terlalu sering mandi air panas dengan sabun keras. Meski biasanya ringan, kondisi ini bisa menurunkan rasa percaya diri dan kenyamanan sehari-hari."}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, '{"text": "Penjelasan: Mengapa Kulit Menjadi Kering"}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, '{"text": "Kulit sehat dilapisi minyak alami (sebum) dan faktor pelembap alami yang menahan air di lapisan terluar. Mandi air panas, sabun dengan deterjen keras, udara kering, dan usia bertambah bisa mengikis lapisan pelindung ini sehingga air menguap lebih cepat. Hasilnya: kulit kehilangan kelembapan, menjadi kasar, dan mudah iritasi. Kabar baiknya, sebagian besar kasus bisa diatasi dengan perawatan rumahan yang konsisten."}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, '{"text": "Alat dan Bahan yang Dibutuhkan"}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, '{"items": ["Minyak kelapa murni atau minyak zaitun", "Madu murni", "Lidah buaya (aloe vera) segar", "Pelembap tanpa pewangi (bila tersedia)", "Air hangat, bukan air panas", "Handuk lembut"]}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, '{"text": "Langkah: Perawatan Alami Kulit Kering"}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, '{"text": "Langkah pertama, ubah kebiasaan mandi: gunakan air hangat suam-suam kuku, batasi durasi 5-10 menit, dan pilih sabun lembut tanpa pewangi tajam. Langkah kedua, kunci kelembapan: dalam 3 menit setelah mandi, saat kulit masih lembap, oleskan minyak kelapa atau pelembap ke seluruh tubuh. Langkah ketiga, masker alami 2-3 kali seminggu: campur 2 sendok madu dengan 1 sendok minyak zaitun, oleskan ke area kering selama 15-20 menit lalu bilas. Langkah keempat, untuk kulit sangat kering di tumit atau siku, oleskan gel lidah buaya segar lalu tutup dengan minyak kelapa sebelum tidur. Langkah kelima, cukupi cairan tubuh dan konsumsi buah serta sayur — hidrasi dari dalam membantu elastisitas kulit."}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, '{"text": "Risiko dan Kapan ke Dokter"}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, '{"items": ["Uji tempel dulu: oleskan bahan alami di lengan dalam, tunggu 24 jam — bila gatal atau merah, hentikan", "Jangan garuk kulit kering: garukan merusak lapisan kulit dan bisa menimbulkan infeksi", "Segera konsultasi ke dokter bila: ruam merah meluas, muncul luka/nanah, gatal hebat berminggu-minggu, atau tak membaik setelah 2-3 minggu perawatan", "Informasi ini bersifat umum dan bukan pengganti nasihat medis — eksim, psoriasis, atau gangguan tiroid butuh diagnosis dokter"]}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, '{"text": "Penyelesaian dan Tindak Lanjut"}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, '{"text": "Jadikan perawatan pelembap sebagai rutinitas harian seperti menyikat gigi: oleskan setelah mandi pagi dan sebelum tidur malam. Evaluasi tiap dua minggu — bila kulit terasa lebih kenyal dan tidak lagi bersisik, rutinitas Anda berhasil. Bila tidak ada perbaikan, catat pola gejalanya dan bawa catatan itu saat konsultasi ke dokter agar diagnosis lebih cepat."}'::jsonb);
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, status, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, '{"text": "Sebuah Lompatan yang Mendunia"}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, '{"text": "Di Pulau Nias, Sumatera Utara, ada tradisi melompati tumpukan batu setinggi sekitar dua meter tanpa alat bantu. Namanya fahombo, atau lompat batu. Atraksi ini begitu terkenal hingga gambarnya pernah menghiasi uang kertas rupiah pecahan seribu. Namun di balik aksinya yang memukau, fahombo menyimpan sejarah panjang tentang perang, kedewasaan, dan identitas sebuah suku."}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, '{"text": "Asal-Usul: Latihan Perang Suku"}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, '{"text": "Dahulu, desa-desa di Nias dikelilingi tembok batu setinggi dua meter sebagai pertahanan. Para pemuda dilatih melompati tembok itu agar bisa menyerbu atau melarikan diri saat perang antardesa. Batu lompat (hombo batu) yang ada sekarang adalah replika tembok pertahanan tersebut — tingginya sekitar 2 meter dengan permukaan atas yang sempit."}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, '{"text": "Makna: Ujian Kedewasaan"}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, '{"text": "Bagi masyarakat Nias, berhasil melompati batu bukan sekadar atraksi. Dahulu, pemuda yang mampu melakukannya dianggap telah dewasa dan layak menjadi prajurit pelindung desa. Keberhasilan melompat melambangkan keberanian, ketangkasan, dan kesiapan memikul tanggung jawab sebagai orang dewasa."}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, '{"text": "Dari Ritual ke Pertunjukan Wisata"}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, '{"text": "Seiring berakhirnya era perang antardesa, fungsi militer fahombo hilang. Tradisi ini kemudian berubah menjadi pertunjukan budaya untuk menyambut tamu dan wisatawan, terutama di Desa Bawomataluo, Nias Selatan. Perubahan ini menyelamatkan tradisi dari kepunahan, meski sebagian kalangan menilai makna sakralnya ikut memudar menjadi sekadar tontonan."}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, '{"text": "Ringkasan"}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, '{"text": "Lompat batu Nias (fahombo) lahir sebagai latihan perang melompati tembok desa setinggi dua meter, berkembang menjadi ujian kedewasaan, dan kini menjadi ikon wisata budaya Indonesia. Tradisinya bertahan karena mampu beradaptasi — dan akan terus hidup selama generasi mudanya mau melompat."}'::jsonb);
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, status, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, '{"text": "Logam yang Tak Lekang oleh Waktu"}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, '{"text": "Selama ribuan tahun, manusia terpesona oleh kilau kuning emas. Ia menjadi mahkota raja, mata uang, perhiasan, hingga komponen ponsel pintar. Tidak seperti besi yang berkarat atau perak yang menghitam, emas nyaris tidak berubah — sifat kimia inilah yang menjadikannya istimewa, jauh sebelum nilainya diakui secara ekonomi."}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, '{"text": "Sifat Kimia: Mengapa Emas Tidak Berkarat"}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, '{"text": "Emas (simbol Au, dari bahasa Latin aurum, nomor atom 79) adalah salah satu unsur paling tidak reaktif. Ia tidak bereaksi dengan oksigen maupun air pada suhu ruang, sehingga tidak berkarat dan tidak ternoda. Sifat lengai inilah yang membuat artefak emas berusia ribuan tahun tetap berkilau seperti baru. Emas juga konduktor listrik yang sangat baik dan logam paling mudah dibentuk: satu gram bisa ditempa menjadi lembaran seluas satu meter persegi."}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, '{"text": "Dari Mana Emas Berasal?"}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, '{"text": "Emas tidak terbentuk di Bumi — ia lahir dari tabrakan bintang neutron di luar angkasa miliaran tahun lalu. Unsur berat seperti emas hanya bisa tercipta dalam ledakan kosmik dahsyat, lalu tersebar dan akhirnya menjadi bagian dari planet kita. Setiap cincin emas yang dipakai hari ini mengandung atom-atom yang lebih tua dari tata surya itu sendiri."}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, '{"text": "Karat dan Penggunaan Modern"}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, '{"text": "Kemurnian emas diukur dalam karat: 24 karat berarti emas murni 99,9 persen, 18 karat berarti 75 persen. Di luar perhiasan, emas adalah material teknologi: melapisi konektor dan papan sirkuit karena tidak teroksidasi, dipakai di satelit sebagai pelindung radiasi, dan menjadi katalis di industri kimia. Indonesia termasuk produsen emas besar dunia, namun penambangannya membawa tantangan lingkungan serius seperti pencemaran merkuri."}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, '{"text": "Ringkasan"}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, '{"text": "Emas istimewa karena sifat kimianya yang lengai, kelenturannya yang luar biasa, dan kelangkaannya yang berasal dari tabrakan bintang. Dari mahkota firaun hingga konektor ponsel, nilainya bertahan ribuan tahun — tetapi di balik kilaunya ada tanggung jawab lingkungan dan kebijaksanaan dalam memanfaatkannya."}'::jsonb);
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, status, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, '{"text": "Tujuan Pembelajaran"}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, '{"text": "Setelah mempelajari materi ini, siswa diharapkan mampu: (1) menjelaskan pengertian perbandingan; (2) membedakan perbandingan senilai dan berbalik nilai; (3) menyelesaikan soal cerita yang berkaitan dengan perbandingan dalam kehidupan sehari-hari."}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, '{"text": "Pengertian Perbandingan"}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, '{"text": "Perbandingan adalah cara membandingkan dua besaran atau lebih yang sejenis, dinyatakan dalam bentuk paling sederhana. Contoh: perbandingan umur kakak dan adik 3 : 2 artinya untuk setiap 3 tahun umur kakak, umur adik 2 tahun. Perbandingan ditulis dengan tanda titik dua dan selalu disederhanakan dengan membagi kedua ruas dengan FPB-nya."}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, '{"text": "Perbandingan Senilai"}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, '{"text": "Perbandingan senilai terjadi ketika dua besaran berubah ke arah yang sama: jika satu bertambah, yang lain ikut bertambah. Rumusnya: a1/a2 = b1/b2. Contoh: harga 3 kg beras Rp36.000, maka harga 5 kg adalah 3/5 = 36.000/x, sehingga x = Rp60.000. Ciri khasnya: semakin banyak barang, semakin besar harga."}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, '{"text": "Perbandingan Berbalik Nilai"}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, '{"text": "Perbandingan berbalik nilai terjadi ketika satu besaran bertambah justru membuat besaran lain berkurang. Rumusnya: a1/a2 = b2/b1 (dibalik). Contoh: persediaan makanan untuk 40 orang cukup 12 hari; jika penghuni menjadi 60 orang, maka 40/60 = x/12, sehingga x = 8 hari. Ciri khasnya: semakin banyak orang, semakin cepat habis."}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, '{"text": "Latihan Soal"}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, '{"items": ["1. Harga 4 buku tulis Rp20.000. Berapa harga 7 buku tulis?", "2. Sebuah proyek selesai 30 hari oleh 8 pekerja. Berapa hari jika pekerjanya 12 orang?", "3. Sederhanakan perbandingan 48 : 60."]}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, '{"text": "Kunci Jawaban"}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, '{"items": ["1. 4/7 = 20.000/x → x = Rp35.000", "2. 8/12 = x/30 → x = 20 hari (berbalik nilai: pekerja naik, waktu turun)", "3. FPB 48 dan 60 adalah 12, jadi 48:60 = 4:5"]}'::jsonb);
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, status, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, '{"text": "Tujuan Pembelajaran"}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, '{"text": "Setelah belajar hari ini, kamu diharapkan bisa: (1) menjelaskan apa itu puisi dengan bahasamu sendiri; (2) menyebutkan ciri-ciri puisi anak; (3) membaca puisi dengan lafal, intonasi, dan ekspresi yang tepat; (4) menulis puisi sederhana tentang hal yang kamu sukai."}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, '{"text": "Apa Itu Puisi?"}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, '{"text": "Puisi adalah karangan yang mengungkapkan perasaan dan pikiran dengan bahasa yang indah dan singkat. Berbeda dengan cerita yang panjang, puisi ditulis baris per baris — setiap baris disebut larik, dan kumpulan larik disebut bait. Puisi itu seperti lagu tanpa musik: enak didengar dan menyentuh hati. Contoh: ‘Ibuku tersayang / Setiap pagi kau bangunkan aku / Menyiapkan sarapan hangat / Terima kasih, Ibu / Kaulah pahlawanku.’"}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, '{"text": "Ciri-Ciri Puisi Anak"}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, '{"items": ["Bahasa sederhana dan mudah dimengerti anak", "Bercerita tentang dunia anak: keluarga, sekolah, hewan, alam", "Mengungkapkan perasaan gembira, sayang, atau kagum", "Bunyi katanya indah, kadang berima (berakhiran sama)", "Ditulis dalam larik dan bait, bukan paragraf panjang"]}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, '{"text": "Cara Membaca Puisi yang Baik"}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, '{"items": ["Lafal: ucapkan setiap kata dengan jelas, jangan terburu-buru", "Intonasi: naikkan suara di bagian gembira, lembutkan di bagian sedih", "Jeda: berhenti sejenak di akhir setiap larik, lebih lama di akhir bait", "Ekspresi: tunjukkan perasaan lewat wajah — tersenyum saat membaca puisi gembira"]}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, '{"text": "Latihan Soal"}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, '{"items": ["1. Apa yang dimaksud dengan larik dan bait?", "2. Sebutkan tiga ciri puisi anak!", "3. Mengapa kita harus memperhatikan intonasi saat membaca puisi?"]}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, '{"text": "Kunci Jawaban"}'::jsonb);
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, '{"items": ["1. Larik adalah baris dalam puisi; bait adalah kumpulan beberapa larik", "2. Bahasa sederhana, tentang dunia anak, mengungkapkan perasaan (atau jawaban lain yang tepat)", "3. Agar pendengar dapat merasakan perasaan dan makna yang ingin disampaikan puisi"]}'::jsonb);
